subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', 'tldextract'], check=False)
from qsing_model import pipeline as P, data as D, augment as A, urls as U
assert U.normalize('https://www.naver.com/', 'strip2') == 'naver.com'
